#!/usr/bin/env bash
# D085: full DB-backed verification against a disposable local Supabase (CI job `migrations`, or locally).
# Applies every migration from scratch, provisions throwaway QA accounts, runs E2E then the direct-REST DB tests.
set -euo pipefail
cd "$(dirname "$0")/.."
if [ "${CI:-}" = "true" ]; then
  # Local stack keys only (generated by `supabase start`); never hosted credentials.
  eval "$(npx supabase@2 status -o env)"
  printf 'NEXT_PUBLIC_SUPABASE_URL=%s\nNEXT_PUBLIC_SUPABASE_ANON_KEY=%s\nSUPABASE_SERVICE_ROLE_KEY=%s\nNEXT_PUBLIC_APP_URL=http://localhost:3000\nSERVICE_MODE=test_demo\n' \
    "$API_URL" "$ANON_KEY" "$SERVICE_ROLE_KEY" > .env.local
fi
grep -Eq '^NEXT_PUBLIC_SUPABASE_URL=http://(127\.0\.0\.1|localhost):' .env.local || { echo "refusing: local Supabase only"; exit 1; }
npx supabase@2 db reset
python3 harness/migration_check.py
node tests/provision.mjs > /dev/null
node tests/provision-admin.mjs
MAILPIT_URL="${MAILPIT_URL:-http://127.0.0.1:54324}" npx playwright test --reporter=line
# security/search reuse rows the E2E run created, so they go after it.
for t in security claims profile-fields search recruiting lists proposals notifications reports privacy uploads safety retention ops analytics consent notes feedback ai-usage email-outbox selection-review ops-metrics usage-ledger promotions test-cancel; do
  echo "== $t"; node "tests/$t.mjs"
done
# Backup → wipe → restore drill (resets the disposable DB, so it runs last).
node harness/restore_drill.mjs
echo "PASS: migrations from scratch + E2E + DB permission tests + restore drill"
